"use strict";
// graceful-fs style monkey patching of the shared fs module object. Writes through the
// wrapper must reach the real module so other packages see the patch.
const fs = require("fs");

const original = fs.readFileSync;
function patchedReadFileSync(...args) {
  patchedReadFileSync.calls++;
  return original.apply(fs, args);
}
patchedReadFileSync.calls = 0;

module.exports = {
  patch() {
    fs.readFileSync = patchedReadFileSync;
    return patchedReadFileSync;
  },
  // Stores this package's own wrapper of statSync on the shared module. The runtime must
  // write the real function, so other code isn't attributed to fs-patcher.
  leak() {
    fs.leakedStat = fs.statSync;
  },
  unpatch() {
    fs.readFileSync = original;
  },
};
